-- 悦航购伙食补给缺失商品补录（Boot 单体模式）
--
-- 目标库：aryn_boot
-- 背景：依据《江远太仓轮南京伙食结算单（7.26）》与系统现有商品对比，将 94 个缺失商品补录进系统。
-- 补录原则（用户要求）：
--   · 不全部上架到船供类目，按商品实际品类挂载到商超分类体系（goods_category）；
--   · 系统无对应分类时新增二级分类：米面粮油>酱菜腌菜、米面粮油>干货、肉禽蛋>腊味；
--   · 商品以结算单名称/包装规格/斤价原口径录入（SPU 名保留结算单商品名，销售价取结算单单价）；
--   · 每个商品配主图（AI 生成占位实拍图），spu_urls 回填并登记 sys_material 素材库。
-- 图片实体：db/assets/provision-grocery-images/（清单见该目录 manifest.tsv）
-- 部署方式：参考 dev-tools/install-product-images.sh，将资产目录图片放入文件存储根目录后执行本脚本；
--           Boot 模式回源 /boot，Cloud 模式经网关 /upms 路由。
-- 特性：可重复执行；仅按 971/972/973 前缀与 3 个新增分类 id 幂等清理自身数据，不触碰存量业务数据；
--       逻辑删除字段 del_flag，禁止物理删除存量。
--
-- 执行：mysql -u root -p aryn_boot < 79provision_grocery_supplement.sql
--
USE `aryn_boot`;
SET NAMES utf8mb4;

-- ---------- 0. 幂等清理（仅本脚本 971/972/973 前缀与 3 个新增分类，不触碰存量） ----------
DELETE FROM `goods_sku` WHERE `id` LIKE '9720000000000000%';
DELETE FROM `goods_spu` WHERE `id` LIKE '9710000000000000%';
DELETE FROM `sys_material` WHERE `id` LIKE '9730000000000000%';
DELETE FROM `goods_category` WHERE `id` IN ('9520000000000000052','9520000000000000053','9520000000000000054');

-- ---------- 1. 新增二级分类（酱菜腌菜 / 干货 / 腊味） ----------

-- ---------- 2. 伙食补给 94 个商品 SPU（按结算单实际品类挂载商超分类） ----------

-- ---------- 3. 对应 SKU（单规格） ----------

-- ---------- 4. 素材库登记（同库 aryn_boot） ----------
